    Column(Modifier.padding(padding).fillMaxSize().testTag("dispatch-outbox")){
        Column(Modifier.fillMaxWidth().padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){
            Text("Dispatch outbox",style=MaterialTheme.typography.headlineSmall)
            Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button({nav.navigate("dispatch/visit/new")},Modifier.weight(1f).testTag("dispatch-new-visit")){Text("New visit")};OutlinedButton({checked=visible.map{it.dispatchVisitId}.toSet()},Modifier.weight(1f).testTag("dispatch-select-all")){Text("Select all shown")}}
            OutlinedTextField(search,{search=it},label={Text("Search Visits")},singleLine=true,modifier=Modifier.fillMaxWidth().testTag("dispatch-search"))
            Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton({choice="status"},Modifier.weight(1f).testTag("dispatch-status-filter")){Text("Status: $statusFilter")};OutlinedButton({choice="date"},Modifier.weight(1f).testTag("dispatch-date-filter")){Text("Date: $dateFilter")}}
