            if(outbox.isEmpty())item{Text("No Dispatch Visits yet.");TextButton({nav.navigate("dispatch/visit/new")}){Text("New visit")}}
            else if(visible.isEmpty())item{Text(if(search.isNotBlank())"No matching Dispatch Visits." else "No Visits match these filters.")}
            items(visible,key={it.dispatchVisitId}){visit->val site=siteMap[visit.siteId];val customer=site?.let{customerMap[it.customerId]};Card(Modifier.fillMaxWidth().testTag("dispatch-outbox-visit-${visit.dispatchVisitId}")){Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=Alignment.Top){Checkbox(visit.dispatchVisitId in checked,{isChecked->checked=if(isChecked)checked+visit.dispatchVisitId else checked-visit.dispatchVisitId},Modifier.testTag("dispatch-select-${visit.dispatchVisitId}"));Column(Modifier.weight(1f).clickable{nav.navigate("dispatch/visit/${visit.dispatchVisitId}")}.testTag("dispatch-open-${visit.dispatchVisitId}")){Text("${visit.serviceDate}${visit.appointmentLocalTime?.let{" · $it"}.orEmpty()}");Text("${visit.managerReference?:visit.dispatchVisitId.take(8)} · ${site?.reference.orEmpty()} ${site?.name?:"Unknown Site"}");customer?.let{Text(it.name,style=MaterialTheme.typography.bodySmall)};Text("${itemCounts[visit.dispatchVisitId]?:0} work items · ${visit.outboxStatus.name.lowercase().replaceFirstChar{it.uppercase()}}${visit.lastExportedGeneration?.let{" · Generation $it"}.orEmpty()}");if((itemCounts[visit.dispatchVisitId]?:0)==0)Text("Needs a work item before export",color=MaterialTheme.colorScheme.error,style=MaterialTheme.typography.bodySmall)}}}}
        }
    }
}

@Composable internal fun DispatchSitePickerDialog(sites:List<SiteEntity>,customers:List<CustomerEntity>,onDismiss:()->Unit,onSelect:(String)->Unit){
