        item{Text("Site / Customer",style=MaterialTheme.typography.titleMedium);Text(chosenSite?.let{site->"${site.reference} · ${site.name}\n${customerMap[site.customerId]?.name.orEmpty()}"}?:"No Site selected");OutlinedButton({showSites=true},Modifier.fillMaxWidth().testTag("dispatch-choose-site"),enabled=!readOnly){Text(if(chosenSite==null)"Choose Site" else "Change Site")}}
        item{Text("Appointment",style=MaterialTheme.typography.titleMedium);OutlinedTextField(date,{date=it},label={Text("Service date · YYYY-MM-DD")},enabled=!readOnly,modifier=Modifier.fillMaxWidth());OutlinedTextField(time,{time=it},label={Text("Appointment time · Optional")},enabled=!readOnly,modifier=Modifier.fillMaxWidth());OutlinedTextField(zone,{zone=it},label={Text("ZoneId")},enabled=!readOnly,modifier=Modifier.fillMaxWidth());OutlinedTextField(manager,{manager=it},label={Text("Manager reference")},enabled=!readOnly,modifier=Modifier.fillMaxWidth());OutlinedTextField(instructions,{instructions=it},label={Text("Dispatch instructions")},enabled=!readOnly,modifier=Modifier.fillMaxWidth())}
