        item{error?.let{Text(it,color=MaterialTheme.colorScheme.error)};if(!readOnly)Button({error=null;when{siteId.isBlank()->error="Choose a Site.";selectedTeams.isEmpty()->error="Choose at least one Team.";participants.isEmpty()->error="Selected Teams need at least one Technician.";runCatching{LocalDate.parse(date)}.isFailure->error="Enter service date as YYYY-MM-DD.";time.isNotBlank()&&runCatching{LocalTime.parse(time)}.isFailure->error="Enter appointment time as HH:mm.";runCatching{ZoneId.of(zone)}.isFailure->error="Enter a valid ZoneId.";else->{busy=true;scope.launch{val result=runCatching{withContext(Dispatchers.IO){svc.saveOutboxVisit(currentDraft())}};withContext(Dispatchers.Main.immediate){result.onSuccess{initialDraft=currentDraft();nav.popBackStack()}.onFailure{if(it is CancellationException)throw it else error=it.message?:"Could not save this Dispatch Visit."};busy=false}}}}},Modifier.fillMaxWidth().testTag("dispatch-save-visit"),enabled=!busy){Text(if(visitId==null)"Save draft" else "Save")};if(loadedVisit?.outboxStatus==DispatchOutboxStatus.DISPATCHED)OutlinedButton({scope.launch{runCatching{withContext(Dispatchers.IO){svc.concludeOutboxVisits(listOf(visitId!!))}}.onSuccess{initialDraft=currentDraft();nav.popBackStack()}.onFailure{if(it is CancellationException)throw it else error=it.message}}},Modifier.fillMaxWidth().testTag("dispatch-conclude-visit"),enabled=!changed&&!busy){Text("Mark concluded")};if(loadedVisit?.outboxStatus==DispatchOutboxStatus.DISPATCHED&&changed)Text("Save or discard your edits before marking this Visit concluded.",style=MaterialTheme.typography.bodySmall);if(readOnly)Button({scope.launch{runCatching{withContext(Dispatchers.IO){svc.reopenOutboxVisits(listOf(visitId!!))}}.onSuccess{load()}.onFailure{if(it is CancellationException)throw it else error=it.message}}},Modifier.fillMaxWidth().testTag("dispatch-reopen-visit")){Text("Reopen")}}
    }
