@Composable internal fun DispatchExportReviewScreen(padding:PaddingValues,nav:NavHostController,ids:List<String>,serviceOverride:DispatchPackageService?=null){
    val context=LocalContext.current;val svc=remember(serviceOverride){serviceOverride?:dispatchService(context)};val scope=rememberCoroutineScope();var sender by rememberSaveable{mutableStateOf("")};var prepared by remember{mutableStateOf<DispatchExportPreparation?>(null)};var currentGenerations by remember{mutableStateOf(emptyMap<String,Int?>())};var error by remember{mutableStateOf<String?>(null)};var refresh by remember{mutableStateOf(0)};var busy by remember{mutableStateOf(false)}
    LaunchedEffect(ids,sender,refresh){prepared=null;if(sender.isNotBlank())runCatching{withContext(Dispatchers.IO){svc.prepareExport(ids,sender) to svc.outboxVisits().filter{it.dispatchVisitId in ids}.associate{it.dispatchVisitId to it.lastExportedGeneration}}}.onSuccess{prepared=it.first;currentGenerations=it.second}.onFailure{if(it is CancellationException)throw it else error=it.message}}
    val visits=prepared?.packageValue?.visits.orEmpty();val itemCount=visits.sumOf{it.work.size};val first=visits.minOfOrNull{it.serviceDate};val last=visits.maxOfOrNull{it.serviceDate}
    LazyColumn(Modifier.padding(padding).fillMaxSize().testTag("dispatch-export-review"),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        item{Text("Export review",style=MaterialTheme.typography.headlineSmall);Text("${ids.size} selected Visits");OutlinedTextField(sender,{sender=it;prepared=null;error=null},label={Text("Sender label")},modifier=Modifier.fillMaxWidth().testTag("dispatch-export-sender"));if(sender.isBlank())Text("Sender label is required before package creation.",color=MaterialTheme.colorScheme.error);if(prepared==null&&sender.isNotBlank())Text("Preparing non-mutating review…")}
        if(visits.isNotEmpty())item{Text("${visits.size} Visits\n${if(first==last)first else "$first – $last"}\n$itemCount work items",Modifier.testTag("dispatch-export-summary"))}
        items(visits,key={it.dispatchVisitId}){visit->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(10.dp)){Text("${visit.serviceDate}${visit.appointmentLocalTime?.let{" · $it"}.orEmpty()}");Text("${visit.managerReference?:visit.dispatchVisitId.take(8)} · ${visit.siteReference}");val current=currentGenerations[visit.dispatchVisitId];Text(when{current==null->"New → generation ${visit.generation}";visit.generation==current->"Unchanged → generation ${visit.generation}";else->"Updated → generation ${visit.generation}"})}}}
        item{error?.let{Text(it,color=MaterialTheme.colorScheme.error)};Button({val review=prepared;if(review==null){error=if(sender.isBlank())"Enter a sender label." else "Wait for the review to finish preparing."}else{busy=true;scope.launch{runCatching{withContext(Dispatchers.IO){svc.createExportFile(review,context.cacheDir)}}.onSuccess{artifact->shareExistingFile(context,artifact.file,WORK_PACKAGE_MIME,"Share ServiceLoop work package");nav.popBackStack()}.onFailure{failure->if(failure is CancellationException)throw failure else{error=if(failure.message?.contains("changed while") == true)"A selected Visit changed while review was open. The review has been refreshed; confirm it again." else failure.message;refresh++}};busy=false}}},Modifier.fillMaxWidth().testTag("dispatch-export-confirm"),enabled=!busy){Text("Create and share package")};Text("Back or Cancel before creation leaves status and generation unchanged.",style=MaterialTheme.typography.bodySmall)}
    }
}

@Composable internal fun CoordinatorHomeActions(nav:NavHostController){
    val context=LocalContext.current;val prefs=remember{context.getSharedPreferences(DISPATCH_PREFS,0)};var enabled by remember{mutableStateOf(prefs.getBoolean(COORDINATOR_ENABLED,false))}
    DisposableEffect(prefs){val listener=android.content.SharedPreferences.OnSharedPreferenceChangeListener{shared,key->if(key==COORDINATOR_ENABLED)enabled=shared.getBoolean(COORDINATOR_ENABLED,false)};prefs.registerOnSharedPreferenceChangeListener(listener);onDispose{prefs.unregisterOnSharedPreferenceChangeListener(listener)}}
    if(enabled)Row(Modifier.fillMaxWidth().testTag("coordinator-home-actions"),horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedButton({nav.navigate("dispatch/technicians")},Modifier.weight(1f)){Text("Technicians",style=MaterialTheme.typography.labelMedium)};OutlinedButton({nav.navigate("dispatch/teams")},Modifier.weight(1f)){Text("Teams",style=MaterialTheme.typography.labelMedium)};Button({nav.navigate("dispatch/create")},Modifier.weight(1f)){Text("Outbox",style=MaterialTheme.typography.labelMedium)}}
}
